"""Lossless transport for separately loaded, live free-Bundle construction.

Three instances keep the surface, rejection records and status separate. The
common network decodes these without carrying the optional construction graph.
Actual source reading, profile/union construction and seam guards are retained
from the existing guarded wrapper by the asset exporter.
"""
from .boundary_quad_bridge_nodes import _join


def packet(g, geometry, diagnostics, valid, seams_valid, key):
    line = g.node('GeometryNodeMeshLine', 'Free Bundle provider status')
    line.inputs['Count'].default_value = 1
    record = line.outputs['Mesh']
    for name, value, kind in (('valid', valid, 'BOOLEAN'), ('seams', seams_valid, 'BOOLEAN'),
                              ('key', key, 'INT'), ('version', 1, 'INT')):
        record = g.store(record, '_fb_provider_'+name, value, kind)
    parts = []
    for name, value in (('Surface', geometry), ('Diagnostics', diagnostics), ('Status', record)):
        node = g.node('GeometryNodeGeometryToInstance', 'Free Bundle packet / '+name)
        g.set(value, node.inputs['Geometry'])
        parts.append(node.outputs['Instances'])
    # Join Geometry prepends multi-input links. Keep decoder ordering explicit.
    return _join(g, *reversed(parts))


def unpack(g, inp):
    info = g.node('GeometryNodeObjectInfo', 'Native free Bundle provider result')
    info.transform_space = 'ORIGINAL'
    g.set(inp.outputs['Free Bundle Result'], info.inputs['Object'])
    source = info.outputs['Geometry']
    size = g.node('GeometryNodeAttributeDomainSize', 'Free Bundle packet size')
    size.component = 'INSTANCES'; g.set(source, size.inputs['Geometry'])
    index = g.node('GeometryNodeInputIndex', 'Free Bundle packet component').outputs[0]
    parts = []
    for ordinal, name in enumerate(('Surface', 'Diagnostics', 'Status')):
        select = g.node('GeometryNodeSeparateGeometry', 'Read free Bundle '+name)
        select.domain = 'INSTANCE'; g.set(source, select.inputs['Geometry'])
        g.set(g.compare(index, ordinal, kind='INT'), select.inputs['Selection'])
        realize = g.node('GeometryNodeRealizeInstances', 'Unpack free Bundle '+name)
        g.set(select.outputs['Selection'], realize.inputs['Geometry'])
        parts.append(realize.outputs['Geometry'])
    status = parts[2]
    read = lambda name, kind: g.sample(status, g.named('_fb_provider_'+name, kind), 0, kind)
    count = g.node('GeometryNodeAttributeDomainSize', 'One free Bundle status')
    count.component = 'MESH'; g.set(status, count.inputs['Geometry'])
    key = inp.outputs['Free Bundle Provider Key']
    transport = g.all(g.compare(size.outputs['Instance Count'], 3, kind='INT'),
        g.compare(count.outputs['Point Count'], 1, kind='INT'),
        g.compare(key, 0, 'GREATER_THAN', 'INT'),
        g.compare(key, 2**24, 'LESS_THAN', 'INT'),
        g.compare(read('key', 'INT'), key, kind='INT'),
        g.compare(read('version', 'INT'), 1, kind='INT'))
    bad = g.node('GeometryNodeMeshLine', 'Missing or mismatched free Bundle provider')
    bad.inputs['Count'].default_value = 1
    diagnostic = bad.outputs['Mesh']
    for name, value in (('st_diagnostic_code', 9), ('st_section_id', -1),
                        ('st_intersection_id', -1), ('st_bundle_id', -1)):
        diagnostic = g.store(diagnostic, name, value, 'INT')
    geometry = g.switch(transport, None, parts[0], 'GEOMETRY')
    # Material IDs are read on the common modifier, so changing its material
    # inputs does not require a Python callback or rebuilding the provider.
    for name, kind in (('Pavement', 0), ('Grass', 1)):
        material = g.node('GeometryNodeSetMaterial', 'Current free Bundle '+name)
        g.set(geometry, material.inputs['Geometry'])
        g.set(g.compare(g.named('st_component_kind'), kind, kind='INT'), material.inputs['Selection'])
        g.set(inp.outputs[name], material.inputs['Material'])
        geometry = material.outputs['Geometry']
    return (geometry, g.switch(transport, diagnostic, parts[1], 'GEOMETRY'),
            g.all(transport, read('valid', 'BOOLEAN')), g.all(transport, read('seams', 'BOOLEAN')))
